{{ config(materialized='table') }}

with
quarantined as (
    select
        source_record_id,
        source_fund_id,
        source_company_id,
        source_valued_on,
        source_value_usd,
        source_method,
        source_valuation_level,
        source_confidence_score,
        valuation_source_system,
        violation_00,
        violation_01
    from {{ ref("investment__holding_valuation_conformed__checked") }}
),
violations as (
    select
        'source_record_id_not_null' as rule_name,
        source_record_id,
        source_fund_id,
        source_company_id,
        source_valued_on,
        source_value_usd,
        source_method,
        source_valuation_level,
        source_confidence_score,
        valuation_source_system
    from quarantined
    where violation_00

    union all

    select
        'source_valued_on_not_null' as rule_name,
        source_record_id,
        source_fund_id,
        source_company_id,
        source_valued_on,
        source_value_usd,
        source_method,
        source_valuation_level,
        source_confidence_score,
        valuation_source_system
    from quarantined
    where violation_01
)

select
    rule_name,
    source_record_id,
    source_fund_id,
    source_company_id,
    source_valued_on,
    source_value_usd,
    source_method,
    source_valuation_level,
    source_confidence_score,
    valuation_source_system
from violations
